vec3 u_xlat0;
vec3 u_xlat1;
vec4 u_xlat2;
mediump vec4 u_xlat16_2;
mediump float u_xlat16_3;
float u_xlat4;
int u_xlati4;
uint u_xlatu4;
bool u_xlatb4;
vec3 u_xlat5;
vec3 u_xlat10;
int u_xlati10;
float u_xlat11;
float u_xlat18;
uint u_xlatu18;
uint u_xlatu19;
void main()
{
ImmCB_1[0] = vec4(1.0,0.0,0.0,0.0);
ImmCB_1[1] = vec4(0.0,1.0,0.0,0.0);
ImmCB_1[2] = vec4(0.0,0.0,1.0,0.0);
ImmCB_1[3] = vec4(0.0,0.0,0.0,1.0);
    u_xlat0.xyz = in_POSITION0.yyy * hlslcc_mtx4x4unity_ObjectToWorld[1].xyz;
    u_xlat0.xyz = hlslcc_mtx4x4unity_ObjectToWorld[0].xyz * in_POSITION0.xxx + u_xlat0.xyz;
    u_xlat0.xyz = hlslcc_mtx4x4unity_ObjectToWorld[2].xyz * in_POSITION0.zzz + u_xlat0.xyz;
    u_xlat0.xyz = u_xlat0.xyz + hlslcc_mtx4x4unity_ObjectToWorld[3].xyz;
    u_xlat1.x = dot(in_NORMAL0.xyz, hlslcc_mtx4x4unity_WorldToObject[0].xyz);
    u_xlat1.y = dot(in_NORMAL0.xyz, hlslcc_mtx4x4unity_WorldToObject[1].xyz);
    u_xlat1.z = dot(in_NORMAL0.xyz, hlslcc_mtx4x4unity_WorldToObject[2].xyz);
    u_xlat18 = dot(u_xlat1.xyz, u_xlat1.xyz);
    u_xlat18 = max(u_xlat18, 1.17549435e-38);
    u_xlat18 = inversesqrt(u_xlat18);
    u_xlat1.xyz = vec3(u_xlat18) * u_xlat1.xyz;
    u_xlat2.xyz = in_TANGENT0.yyy * hlslcc_mtx4x4unity_ObjectToWorld[1].xyz;
    u_xlat2.xyz = hlslcc_mtx4x4unity_ObjectToWorld[0].xyz * in_TANGENT0.xxx + u_xlat2.xyz;
    u_xlat2.xyz = hlslcc_mtx4x4unity_ObjectToWorld[2].xyz * in_TANGENT0.zzz + u_xlat2.xyz;
    u_xlat18 = dot(u_xlat2.xyz, u_xlat2.xyz);
    u_xlat18 = max(u_xlat18, 1.17549435e-38);
    u_xlat18 = inversesqrt(u_xlat18);
    vs_INTERP2.xyz = vec3(u_xlat18) * u_xlat2.xyz;
    u_xlat2 = u_xlat0.yyyy * hlslcc_mtx4x4unity_MatrixVP[1];
    u_xlat2 = hlslcc_mtx4x4unity_MatrixVP[0] * u_xlat0.xxxx + u_xlat2;
    u_xlat2 = hlslcc_mtx4x4unity_MatrixVP[2] * u_xlat0.zzzz + u_xlat2;
    gl_Position = u_xlat2 + hlslcc_mtx4x4unity_MatrixVP[3];
    u_xlat16_3 = min(_AdditionalLightsCount.x, unity_LightData.y);
    u_xlatu18 =  uint(int(u_xlat16_3));
    u_xlat16_2.y = float(0.0);
    u_xlat16_2.z = float(0.0);
    u_xlat16_2.w = float(0.0);
    for(uint u_xlatu_loop_1 = uint(0u) ; u_xlatu_loop_1<u_xlatu18 ; u_xlatu_loop_1++)
    {
        u_xlatu4 = uint(u_xlatu_loop_1 >> (2u & uint(0x1F)));
        u_xlati10 = int(uint(u_xlatu_loop_1 & 3u));
        u_xlat4 = dot(unity_LightIndices[int(u_xlatu4)], ImmCB_1[u_xlati10]);
        u_xlati4 = int(u_xlat4);
        u_xlat10.xyz = (-u_xlat0.xyz) * _AdditionalLightsPosition[u_xlati4].www + _AdditionalLightsPosition[u_xlati4].xyz;
        u_xlat5.x = dot(u_xlat10.xyz, u_xlat10.xyz);
        u_xlat5.x = max(u_xlat5.x, 6.10351562e-05);
        u_xlat11 = inversesqrt(u_xlat5.x);
        u_xlat10.xyz = u_xlat10.xyz * vec3(u_xlat11);
        u_xlat11 = float(1.0) / float(u_xlat5.x);
        u_xlat5.x = u_xlat5.x * _AdditionalLightsAttenuation[u_xlati4].x;
        u_xlat16_3 = (-u_xlat5.x) * u_xlat5.x + 1.0;
        u_xlat16_3 = max(u_xlat16_3, 0.0);
        u_xlat16_3 = u_xlat16_3 * u_xlat16_3;
        u_xlat5.x = u_xlat16_3 * u_xlat11;
        u_xlat16_3 = dot(_AdditionalLightsSpotDir[u_xlati4].xyz, u_xlat10.xyz);
        u_xlat16_3 = u_xlat16_3 * _AdditionalLightsAttenuation[u_xlati4].z + _AdditionalLightsAttenuation[u_xlati4].w;
        u_xlat16_3 = clamp(u_xlat16_3, 0.0, 1.0);
        u_xlat16_3 = u_xlat16_3 * u_xlat16_3;
        u_xlat5.x = u_xlat16_3 * u_xlat5.x;
        u_xlat5.xyz = u_xlat5.xxx * _AdditionalLightsColor[u_xlati4].xyz;
        u_xlat16_3 = dot(u_xlat1.xyz, u_xlat10.xyz);
        u_xlat16_3 = clamp(u_xlat16_3, 0.0, 1.0);
        u_xlat16_2.yzw = u_xlat5.xyz * vec3(u_xlat16_3) + u_xlat16_2.yzw;
    }
    vs_INTERP2.w = in_TANGENT0.w;
    vs_INTERP3 = in_TEXCOORD0;
    vs_INTERP4 = in_TEXCOORD1;
    vs_INTERP5 = in_COLOR0;
    phase0_Output0_8 = vec4(0.0, 0.0, 0.0, 0.0);
    u_xlat16_2.x = 0.0;
    vs_INTERP10 = u_xlat16_2;
    vs_INTERP11 = vec4(0.0, 0.0, 0.0, 0.0);
    vs_INTERP0.xyz = u_xlat0.xyz;
    vs_INTERP1.xyz = u_xlat1.xyz;
    vs_INTERP6.xyz = vec3(0.0, 0.0, 0.0);
    vs_INTERP9.xyz = vec3(0.0, 0.0, 0.0);
vs_INTERP7 = phase0_Output0_8.xy;
vs_INTERP8 = phase0_Output0_8.zw;
    return;
}


