in highp  vec3 vs_INTERP0;
in highp  vec3 vs_INTERP1;
in highp  vec4 vs_INTERP3;
in highp  vec4 vs_INTERP10;
layout(location = 0) out mediump vec4 SV_Target0;
vec4 u_xlat0;
mediump vec3 u_xlat16_0;
vec3 u_xlat1;
mediump vec4 u_xlat16_1;
mediump vec3 u_xlat16_2;
mediump vec3 u_xlat16_3;
mediump vec4 u_xlat16_4;
mediump vec3 u_xlat16_5;
vec3 u_xlat6;
float u_xlat21;
bool u_xlatb21;
float u_xlat22;
mediump float u_xlat16_23;
void main()
{
    u_xlat16_0.xyz = texture(Material_Texture2D_0, vs_INTERP3.xy, _GlobalMipBias.x).xyz;
    u_xlat21 = dot(u_xlat16_0.xyz, u_xlat16_0.xyz);
    u_xlat21 = inversesqrt(u_xlat21);
    u_xlat1.xyz = vec3(u_xlat21) * u_xlat16_0.xyz;
    u_xlat0.x = dot(u_xlat16_0.xyz, vec3(0.212639004, 0.715168655, 0.0721923187));
    u_xlat0.x = max(u_xlat0.x, 0.0);
    u_xlat0.x = log2(u_xlat0.x);
    u_xlat0.x = u_xlat0.x * Color_Contrast;
    u_xlat0.x = exp2(u_xlat0.x);
    u_xlat0.xyz = u_xlat0.xxx * u_xlat1.xyz;
    u_xlat16_2.xyz = u_xlat0.xyz * vec3(0.959999979, 0.959999979, 0.959999979);
    u_xlat0.xyz = (-vs_INTERP0.xyz) + _WorldSpaceCameraPos.xyz;
    u_xlat21 = dot(u_xlat0.xyz, u_xlat0.xyz);
    u_xlat21 = inversesqrt(u_xlat21);
    u_xlat0.xyz = vec3(u_xlat21) * u_xlat0.xyz;
    u_xlatb21 = unity_OrthoParams.w==0.0;
    u_xlat16_3.x = (u_xlatb21) ? u_xlat0.x : hlslcc_mtx4x4unity_MatrixV[0].z;
    u_xlat16_3.y = (u_xlatb21) ? u_xlat0.y : hlslcc_mtx4x4unity_MatrixV[1].z;
    u_xlat16_3.z = (u_xlatb21) ? u_xlat0.z : hlslcc_mtx4x4unity_MatrixV[2].z;
    u_xlat0.x = dot(vs_INTERP1.xyz, vs_INTERP1.xyz);
    u_xlat0.x = inversesqrt(u_xlat0.x);
    u_xlat0.xyz = u_xlat0.xxx * vs_INTERP1.xyz;
    u_xlat16_23 = dot((-u_xlat16_3.xyz), u_xlat0.xyz);
    u_xlat16_23 = u_xlat16_23 + u_xlat16_23;
    u_xlat16_4.xyz = u_xlat0.xyz * (-vec3(u_xlat16_23)) + (-u_xlat16_3.xyz);
    u_xlat16_1 = textureLod(unity_SpecCube0, u_xlat16_4.xyz, 6.0);
    u_xlat16_23 = u_xlat16_1.w + -1.0;
    u_xlat16_23 = unity_SpecCube0_HDR.w * u_xlat16_23 + 1.0;
    u_xlat16_23 = max(u_xlat16_23, 0.0);
    u_xlat16_23 = log2(u_xlat16_23);
    u_xlat16_23 = u_xlat16_23 * unity_SpecCube0_HDR.y;
    u_xlat16_23 = exp2(u_xlat16_23);
    u_xlat16_23 = u_xlat16_23 * unity_SpecCube0_HDR.x;
    u_xlat16_4.xyz = u_xlat16_1.xyz * vec3(u_xlat16_23);
    u_xlat16_23 = dot(u_xlat0.xyz, u_xlat16_3.xyz);
    u_xlat16_23 = clamp(u_xlat16_23, 0.0, 1.0);
    u_xlat1.xyz = u_xlat16_3.xyz + _MainLightPosition.xyz;
    u_xlat16_23 = (-u_xlat16_23) + 1.0;
    u_xlat16_23 = u_xlat16_23 * u_xlat16_23;
    u_xlat16_23 = u_xlat16_23 * u_xlat16_23;
    u_xlat16_23 = u_xlat16_23 * 2.23517418e-08 + 0.0399999991;
    u_xlat22 = u_xlat16_23 * 0.5;
    u_xlat16_3.xyz = vec3(u_xlat22) * u_xlat16_4.xyz;
    u_xlat16_23 = u_xlat0.y * u_xlat0.y;
    u_xlat16_23 = u_xlat0.x * u_xlat0.x + (-u_xlat16_23);
    u_xlat16_4 = u_xlat0.yzzx * u_xlat0.xyzz;
    u_xlat16_5.x = dot(unity_SHBr, u_xlat16_4);
    u_xlat16_5.y = dot(unity_SHBg, u_xlat16_4);
    u_xlat16_5.z = dot(unity_SHBb, u_xlat16_4);
    u_xlat16_4.xyz = unity_SHC.xyz * vec3(u_xlat16_23) + u_xlat16_5.xyz;
    u_xlat16_23 = dot(u_xlat0.xyz, _MainLightPosition.xyz);
    u_xlat16_23 = clamp(u_xlat16_23, 0.0, 1.0);
    u_xlat22 = u_xlat16_23 * unity_LightData.z;
    u_xlat6.xyz = vec3(u_xlat22) * _MainLightColor.xyz;
    u_xlat0.w = 1.0;
    u_xlat16_5.x = dot(unity_SHAr, u_xlat0);
    u_xlat16_5.y = dot(unity_SHAg, u_xlat0);
    u_xlat16_5.z = dot(unity_SHAb, u_xlat0);
    u_xlat16_4.xyz = u_xlat16_4.xyz + u_xlat16_5.xyz;
    u_xlat16_3.xyz = u_xlat16_4.xyz * u_xlat16_2.xyz + u_xlat16_3.xyz;
    u_xlat0.x = dot(u_xlat1.xyz, u_xlat1.xyz);
    u_xlat0.x = max(u_xlat0.x, 1.17549435e-38);
    u_xlat0.x = inversesqrt(u_xlat0.x);
    u_xlat0.xyz = u_xlat0.xxx * u_xlat1.xyz;
    u_xlat0.x = dot(_MainLightPosition.xyz, u_xlat0.xyz);
    u_xlat0.x = clamp(u_xlat0.x, 0.0, 1.0);
    u_xlat16_23 = u_xlat0.x * u_xlat0.x;
    u_xlat0.x = max(u_xlat16_23, 0.100000001);
    u_xlat0.x = u_xlat0.x * 6.00012016;
    u_xlat0.x = float(1.0) / u_xlat0.x;
    u_xlat16_23 = u_xlat0.x + -6.10351562e-05;
    u_xlat16_4.xyz = vec3(u_xlat16_23) * vec3(0.0399999991, 0.0399999991, 0.0399999991) + u_xlat16_2.xyz;
    u_xlat16_3.xyz = u_xlat16_4.xyz * u_xlat6.xyz + u_xlat16_3.xyz;
    u_xlat16_2.xyz = vs_INTERP10.yzw * u_xlat16_2.xyz + u_xlat16_3.xyz;
    u_xlat16_2.xyz = SelectionColor.www * SelectionColor.xyz + u_xlat16_2.xyz;
    SV_Target0.xyz = min(u_xlat16_2.xyz, vec3(65504.0, 65504.0, 65504.0));
    SV_Target0.w = 1.0;
    return;
}

